#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;
const int MAXN = 1e5 + 5;

vector<int> adj[MAXN];
array<long long, 4> dp[MAXN];
int a[MAXN];

// 计算 num 中因子 f 的个数
int get_factor(int num, int f) {
    int cnt = 0;
    while (num % f == 0) {
        cnt++;
        num /= f;
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i)
        cin >> a[i];
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // 栈模拟后序遍历，元组为 (节点, 父节点, 是否已访问)
    stack<tuple<int, int, bool>> st;
    st.emplace(1, -1, false);
    long long ans = 0;

    while (!st.empty()) {
        auto [u, p, visited] = st.top();
        st.pop();

        if (!visited) {
            // 计算当前节点的因子状态
            int cnt2 = get_factor(a[u], 2);
            int cnt5 = get_factor(a[u], 5);
            bool has2 = cnt2 >= 1;
            bool has5 = cnt5 >= 1;
            int state = (has2 << 1) | has5;
            dp[u].fill(0);
            dp[u][state] = 1;

            // 先处理子节点，再回溯
            st.emplace(u, p, true);
            for (int v : adj[u]) {
                if (v != p) {
                    st.emplace(v, u, false);
                }
            }
        } else {
            // 合并所有子节点的 dp
            for (int v : adj[u]) {
                if (v == p) continue;
                array<long long, 4> tmp = {0};
                for (int i = 0; i < 4; ++i) {
                    if (dp[u][i] == 0) continue;
                    for (int j = 0; j < 4; ++j) {
                        if (dp[v][j] == 0) continue;
                        int k = i | j;
                        tmp[k] = (tmp[k] + dp[u][i] * dp[v][j]) % MOD;
                    }
                }
                for (int k = 0; k < 4; ++k) {
                    dp[u][k] = (dp[u][k] + tmp[k]) % MOD;
                }
            }
            // 统计以 u 为最浅节点的幸运集
            ans = (ans + dp[u][3]) % MOD;
        }
    }

    cout << ans << "\n";
    return 0;
}
